  button.disabled=true;button.textContent="Sending…";out.textContent="Sending your request. Please wait.";
  try{const selectedTime=host.querySelector("#meet-time").value;const timeMatch=selectedTime.match(/(\d{1,2}):(\d{2})\s*(a\.m\.|p\.m\.)/i);if(!timeMatch)throw new Error("Please choose a valid start time.");let hh=Number(timeMatch[1])%12;if(/p/i.test(timeMatch[3]))hh+=12;const mm=Number(timeMatch[2]);const startsAt=meetLocalIso(date.value,hh,mm);const eventDates=[data.featuredEvent,data.specialEvent].concat(data.additionalSpecialEvents||[]).filter(x=>x&&x.active!==false).map(parts).filter(Boolean).map(p=>key(new Date(p.y,p.m,p.d)));const response=await fetch("https://ovnbbpcrwbvotyevghcx.supabase.co/functions/v1/meet-greet",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"request",first_name:form.elements.first_name.value,last_name:form.elements.last_name.value,email:form.elements.email.value,kittens:Array.from(form.querySelectorAll('input[name="kittens[]"]:checked')).map(x=>x.value),application_approved:applicationApproved,starts_at:startsAt,additional_notes:form.elements.additional_notes.value,event_dates:eventDates,site_base_url:new URL("../",window.location.href).href,_honey:form.elements._honey.value})});const result=await response.json();if(!response.ok)throw new Error(result.error||"Your request could not be sent.");form.reset();date.value="";applicationSubmitted=false;applicationApproved=false;form.querySelectorAll('input[name="application_approved"]').forEach(x=>x.required=false);updateApplicationGate();updateWeekendNotice();draw();status.textContent="Select an available date on the calendar.";out.textContent="Thank you! Your request has been received. It is not confirmed until we review it and email you.";}
  catch(err){out.textContent="Sorry, your request could not be sent right now. Please try again later or email pawsandpurrsfosters@gmail.com directly.";}
